// Builds shared/screens.generated.js from the menu in client/src/components/Layout.jsx, so Ask always knows every screen.
// Run: node scripts/gen-screens.mjs   (server/test/screens.test.js fails when the generated file is out of date)
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
export function buildScreens() {
  const src = fs.readFileSync(path.join(root, 'client/src/components/Layout.jsx'), 'utf8');
  const start = src.indexOf('const NAV = ['), end = src.indexOf('\n];', start);
  const block = src.slice(start, end);
  const out = []; const seen = new Set();
  const push = (section, label, to) => { const k = `${section}|${label}|${to}`; if (!seen.has(k)) { seen.add(k); out.push({ section, label, path: to }); } };
  // one NAV entry per top-level "{ label:" ... balanced by splitting on lines that start an entry
  for (const chunk of block.split(/\n  \{ (?=label:)/).slice(1)) {
    const section = /^label: (?:'([^']*)'|"([^"]*)")/.exec(chunk); const name = section[1] ?? section[2];
    const top = /\bto: '([^']*)'/.exec(chunk.split('children:')[0]);
    if (top) push(name, name, top[1]);
    const kids = chunk.includes('children:') ? chunk.slice(chunk.indexOf('children:')) : '';
    for (const m of kids.matchAll(/\['([^']+)', '(\/[^']*)'/g)) push(name, m[1], m[2]);
  }
  return out;
}
export const render = (list) => `// GENERATED by scripts/gen-screens.mjs from the menu in client/src/components/Layout.jsx. Do not edit by hand.\nexport const SCREENS = ${JSON.stringify(list, null, 1).replace(/\n\s*/g, ' ').replace(/\{ "section"/g, '\n  { "section"').replace(/\[ /, '[').replace(/ \]$/, '\n]')};\n`;
if (process.argv[1] === fileURLToPath(import.meta.url)) { const l = buildScreens(); fs.writeFileSync(path.join(root, 'shared/screens.generated.js'), render(l)); console.log(l.length, 'screens'); }
